result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/calc.py", "content": """"Recursive-descent parser and evaluator for arithmetic expressions.

Grammar:
    expression := term (('+' | '-') term)*
    term       := factor (('*' | '/' | '%') factor)*
    factor     := unary ('**' factor)?          # right-associative
    unary      := '-' unary | primary
    primary    := NUMBER | '(' expression ')'
"""

import sys


class ParseError(Exception):
    """Raised on invalid input.

    Attributes:
        offset: 0-based character offset in the input where the error occurred.
        message: description naming the unexpected token.
    """

    def __init__(self, offset, message):
        super().__init__(message)
        self.offset = offset
        self.message = message


# ---------------------------------------------------------------- tokenizer

class Token:
    __slots__ = ("kind", "value", "offset")

    def __init__(self, kind, value, offset):
        self.kind = kind        # 'NUMBER', 'PLUS', ..., 'EOF'
        self.value = value      # numeric value for NUMBER, text otherwise
        self.offset = offset    # 0-based character offset


_OPERATORS = {
    "**": "POW",
    "+": "PLUS",
    "-": "MINUS",
    "*": "STAR",
    "/": "SLASH",
    "%": "PERCENT",
    "(": "LPAREN",
    ")": "RPAREN",
}


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and text[i + 1].isdigit()):
            start = i
            while i < n and text[i].isdigit():
                i += 1
            is_float = False
            if i < n and text[i] == ".":
                # reject "1.2.3" style by only consuming one dot
                is_float = True
                i += 1
                while i < n and text[i].isdigit():
                    i += 1
            lexeme = text[start:i]
            if i < n and text[i] == ".":
                raise ParseError(i + 1, f"unexpected token '{text[i:]}'")
            value = float(lexeme) if is_float else int(lexeme)
            tokens.append(Token("NUMBER", value, start))
            continue
        two = text[i:i + 2]
        if two == "**":
            tokens.append(Token("POW", "**", i))
            i += 2
            continue
        if ch in _OPERATORS:
            kind = _OPERATORS[ch]
            tokens.append(Token(kind, ch, i))
            i += 1
            continue
        raise ParseError(i, f"unexpected token '{ch}'")
    tokens.append(Token("EOF", None, n))
    return tokens


# ------------------------------------------------------------------ parser

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        return self.tokens[self.pos]

    def _advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _expect(self, kind):
        tok = self._peek()
        if tok.kind != kind:
            shown = "end of input" if tok.kind == "EOF" else f"'{tok.value}'"
            raise ParseError(tok.offset, f"unexpected token {shown}")
        return self._advance()

    def parse(self):
        value = self._expression()
        tok = self._peek()
        if tok.kind != "EOF":
            shown = f"'{tok.value}'"
            raise ParseError(tok.offset, f"unexpected token {shown}")
        return value

    def _expression(self):
        value = self._term()
        while self._peek().kind in ("PLUS", "MINUS"):
            op = self._advance()
            rhs = self._term()
            if op.kind == "PLUS":
                value = value + rhs
            else:
                value = value - rhs
        return value

    def _term(self):
        value = self._factor()
        while self._peek().kind in ("STAR", "SLASH", "PERCENT"):
            op = self._advance()
            rhs = self._factor()
            if op.kind == STAR := "STAR":
                value = value * rhs
            elif op.kind == "SLASH":
                value = value / rhs
            else:
                value = value % rhs
        return value

    def _factor(self):
        base = self._unary()
        if self._peek().kind == "POW":
            self._advance()
            exponent = self._factor()  # right-associative recursion
            return base ** exponent
        return base

    def _unary(self):
        if self._peek().kind == "MINUS":
            self._advance()
            return -self._unary()
        return self._primary()

    def _primary(self):
        tok = self._peek()
        if tok.kind == "NUMBER":
            self._advance()
            return tok.value
        if tok.kind == "LPAREN":
            self._advance()
            value = self._expression()
            closing = self._peek()
            if closing.kind != "RPAREN":
                shown = "end of input" if closing.kind == "EOF" else f"'{closing.value}'"
                raise ParseError(closing.offset, f"unexpected token {shown}")
            self._advance()
            return value
        shown = "end of input" if tok.kind == "EOF" else f"'{tok.value}'"
        raise ParseError(tok.offset, f"unexpected token {shown}")


def evaluate(text):
    """Parse and evaluate an arithmetic expression string; return a number."""
    return Parser(_tokenize(text)).parse()


def main(argv):
    if len(argv) != 2:
        print(f"usage: {argv[0]} \"<expression>\"", file=sys.stderr)
        return 2
    try:
        result = evaluate(argv[1])
    except ParseError as exc:
        print(f"error at offset {exc.offset}: {exc.message}", file=sys.stderr)
        return 1
    except ZeroDivisionError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(result)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"})
