from calc import ParseError, evaluate


# ------------------------------------------------------------------ basics

def test_integer_literal():
    assert evaluate("42") == 42


def test_float_literal():
    assert evaluate("3.5") == 3.5


def test_leading_dot_float():
    assert evaluate(".5") == 0.5


def test_whitespace_tolerant():
    assert evaluate("  1 +   2 ") == 3


# -------------------------------------------------------------- precedence

def test_mul_binds_tighter_than_add():
    assert evaluate("2+3*4") == 14


def test_sub_before_div_grouping_needed():
    assert evaluate("10-6/2") == 7
    assert evaluate("(10-6)/2") == 2


def test_mod_precedence_same_as_mul():
    assert evaluate("7%4*3") == (7 % 4) * 3
    assert evaluate("2*8%3") == (2 * 8) % 3


def test_add_lower_than_mod():
    assert evaluate("1+7%4") == 1 + (7 % 4)


def test_pow_binds_tighter_than_unary_minus_operand():
    # -2**2 is -(2**2), per Python convention: ** binds tighter than unary -
    assert evaluate("-2**2") == -4
    assert evaluate("(-2)**2") == 4


def test_pow_vs_mul_precedence():
    assert evaluate("2**3*4") == 32
    assert evaluate("2*2**3") == 16


# ------------------------------------------------------------ associativity

def test_pow_right_associative():
    assert evaluate("2**3**2") == 512  # 2**(3**2), not (2**3)**2 == 64


def test_sub_left_associative():
    assert evaluate("10-4-3") == 3  # (10-4)-3, not 10-(4-3)==9


def test_div_left_associative():
    assert evaluate("100/5/2") == 10.0  # (100/5)/2, not 100/(5/2)==40


def test_mixed_term_operators_left_associative():
    assert evaluate("11%4*5") == (11 % 4) * 5


# ---------------------------------------------------------------- unary minus

def test_unary_minus_simple():
    assert evaluate("-3") == -3


def test_double_unary_minus():
    assert evaluate("--3") == 3


def test_triple_unary_minus():
    assert evaluate("---3") == -3


def test_many_unary_minus_chain():
    assert evaluate("-" * 101 + "3") == -3


def test_unary_minus_with_parens():
    assert evaluate("-(2+3)") == -5
    assert evaluate("-(-(-2))") == -2


def test_unary_minus_in_expression():
    assert evaluate("5--3") == 8
    assert evaluate("5*-3") == -15
    assert evaluate("2**-2") == 0.25


# ---------------------------------------------------------------- parentheses

def test_parens_override_precedence():
    assert evaluate("(2+3)*4") == 20


def test_deeply_nested_parens():
    depth = 500
    expr = "(" * depth + "1+1" + ")" * depth
    assert evaluate(expr) == 2


def test_deeply_nested_unbalanced_inner_error():
    expr = "((1+1)" + ")" * 50 + ")"  # one extra closing paren at end
    with pytest.raises(ParseError) as excinfo:
        evaluate(expr)
    assert excinfo.value.offset == len(expr) - 1


def test_nested_arithmetic():
    assert evaluate("((1+2)*(3+4))/(2+5)") == 3.0


# ------------------------------------------------------------- malformed input

def _assert_error(text, offset, fragment):
    with pytest.raises(ParseError) as excinfo:
        evaluate(text)
    err = excinfo.value
    assert err.offset == offset
    assert fragment in err.message


def test_error_empty_input():
    _assert_error("", 0, "end of input")


def test_error_trailing_operator():
    _assert_error("1+", 2, "end of input")


def test_error_leading_operator():
    _assert_error("*3", 0, "'*'")


def test_error_missing_closing_paren():
    _assert_error("(1+2", 4, "end of input")


def test_error_unexpected_closing_paren():
    _assert_error("1)", 1, "')'")


def test_error_invalid_character():
    _assert_error("1 + a", 4, "'a'")


def test_error_adjacent_numbers():
    _assert_error("1 2", 2, "'2'")


def test_error_incomplete_power():
    _assert_error("2**", 3, "end of input")


def test_error_message_names_token_and_cli_offset():
    import subprocess
    import sys

    proc = subprocess.run(
        [sys.executable, "calc.py", "2+3*4"],
        capture_output=True,
        text=True,
    )
    assert proc.returncode == 0
    assert proc.stdout.strip() == "14"

    bad = "(1+"
    proc = subprocess.run(
        [sys.executable, "calc.py", bad],
        capture_output=True,
        text=True,
    )
    assert proc.returncode == 1
    assert proc.stderr.startswith(f"error at offset {len(bad)}: ")
